import { expect, story } from "../../storybook/playwright/story"

story("native provider editing keeps the key hidden and model selection uses the available catalog", async ({ mount, page }) => {
  const root = await mount("openagi-configuration--native-editors")
  await expect(root.getByText("Global network proxy")).toBeVisible()
  await root.getByRole("button", { name: "Edit provider", exact: true }).click()
  const dialog = page.getByRole("dialog")
  await expect(dialog.getByLabel("API key", { exact: true })).toHaveValue("")
  await expect(dialog.getByLabel("API key", { exact: true })).toHaveAttribute("type", "password")
  await dialog.getByLabel("API base URL", { exact: true }).fill("http://new-gateway.invalid/v1")
  await dialog.getByRole("button", { name: "Save", exact: true }).click()
  await expect(root.getByLabel("Recorded configuration actions")).toContainText("provider primary http://new-gateway.invalid/v1 keyChanged=false")
  await root.getByRole("button", { name: "Model settings", exact: true }).click()
  await expect(root.getByText("TypeSafe / jev-latest", { exact: true })).toBeVisible()
  await root.getByRole("button", { name: "Choose model", exact: true }).first().click()
  await expect(root.getByLabel("Recorded configuration actions")).toContainText("catalog primary")
  await page.getByRole("dialog").getByRole("button", { name: "Save", exact: true }).click()
  await expect(root.getByLabel("Recorded configuration actions")).toContainText("model heavy heavy")
})

story("adds a custom provider with manual model IDs and hidden authentication headers", async ({ mount, page }) => {
  const root = await mount("openagi-configuration--native-editors")
  await root.getByRole("button", { name: "Add provider", exact: true }).click()
  const dialog = page.getByRole("dialog")
  await dialog.getByLabel("Provider ID", { exact: true }).fill("custom-gateway")
  await dialog.getByLabel("Display name", { exact: true }).fill("My gateway")
  await dialog.getByLabel("API base URL", { exact: true }).fill("http://manual-gateway.invalid/v1")
  await dialog.getByLabel("API key", { exact: true }).fill("fixture-key")
  await dialog.getByText("Specify model IDs manually", { exact: true }).click()
  await expect(dialog.getByRole("switch", { name: "Specify model IDs manually" })).toBeChecked()
  await dialog.getByRole("button", { name: "Add model", exact: true }).click()
  await dialog.getByLabel("Model ID", { exact: true }).fill("gpt-6.1-sol")
  await dialog.getByLabel("Model name", { exact: true }).fill("My heavy model")
  await dialog.getByRole("button", { name: "Add header", exact: true }).click()
  await dialog.getByLabel("Header name", { exact: true }).fill("x-auth")
  await expect(dialog.getByLabel("Header value", { exact: true })).toHaveAttribute("type", "password")
  await dialog.getByLabel("Header value", { exact: true }).fill("fixture-header-value")
  await dialog.getByRole("button", { name: "Save", exact: true }).click()
  await expect(root.getByLabel("Recorded configuration actions")).toContainText("manual custom-gateway gpt-6.1-sol headers=x-auth")
  await expect(root.getByText("My gateway", { exact: true })).toBeVisible()
  await expect(root).not.toContainText("fixture-key")
  await expect(root).not.toContainText("fixture-header-value")
})
